27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "possible_duplicate")
73	    private Boolean possibleDuplicate;
74	
75	    @Column(name = "possible_duplicate_of")
76	    private Integer possibleDuplicateOf;
77	
78	    @Transient
79	    private Integer householdMemberCount;
80	
81	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
82	    private Set<Pet> pets;
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = telephone;
106	    }
107	
108	    public String getEmail() {
109	        return this.email;
110	    }
111	
112	    public void setEmail(String email) {
113	        this.email = email;
114	    }
115	
116	    public String getPostcode() {
117	        return this.postcode;
118	    }
119	
120	    public void setPostcode(String postcode) {
121	        this.postcode = postcode;
122	    }
123	
124	    public LocalDate getRegistrationDate() {
125	        return this.registrationDate;
126	    }
