132	    public LocalDate getBirthDate() {
133	        return this.birthDate;
134	    }
135	
136	    public void setBirthDate(LocalDate birthDate) {
137	        this.birthDate = birthDate;
138	    }
139	
140	    public String getCustomerCode() {
141	        return this.customerCode;
142	    }
143	
144	    public void setCustomerCode(String customerCode) {
145	        this.customerCode = customerCode;
146	    }
147	
148	    public String getHouseholdId() {
149	        return this.householdId;
150	    }
151	
152	    public void setHouseholdId(String householdId) {
153	        this.householdId = householdId;
154	    }
155	
156	    public Integer getNamesakeCount() {
157	        return this.namesakeCount;
158	    }
159	
160	    public void setNamesakeCount(Integer namesakeCount) {
161	        this.namesakeCount = namesakeCount;
162	    }
163	
164	    public Boolean getPossibleDuplicate() {
165	        return this.possibleDuplicate;
166	    }
167	
168	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
169	        this.possibleDuplicate = possibleDuplicate;
170	    }
171	
172	    public Integer getPossibleDuplicateOf() {
173	        return this.possibleDuplicateOf;
174	    }
175	
176	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
177	        this.possibleDuplicateOf = possibleDuplicateOf;
178	    }
